using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://services/{serviceName}",
        Name = "Service Endpoint",
        MimeType = "application/json"),
     Description("Returns endpoint configuration for a named service.")]
    public static string GetServiceConfig(string serviceName)
    {
        var endpoints = new Dictionary<string, object>
        {
            ["auth"]    = new { Url = "https://auth.example.com",    Port = 443 },
            ["storage"] = new { Url = "https://storage.example.com", Port = 443 },
            ["cache"]   = new { Url = "https://cache.example.com",   Port = 6379 }
        };

        if (!endpoints.TryGetValue(serviceName, out var endpoint))
            return JsonSerializer.Serialize(new { Error = $"Unknown service: {serviceName}" });

        return JsonSerializer.Serialize(endpoint, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Checks whether a feature flag is enabled.")]
    public static string CheckFeatureFlag(
        [Description("The feature flag name to check (e.g., 'DarkMode', 'BetaAccess')")] string flagName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["Notifications"] = true
        };

        return flags.TryGetValue(flagName, out var enabled)
            ? $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}."
            : $"Unknown feature flag: '{flagName}'.";
    }
}

